using Invoicing.Legacy;

namespace Invoicing;

/// <summary>Exports an invoice as a PDF byte stream.</summary>
public sealed class PdfExporter
{
    public byte[] Export(Invoice invoice)
    {
        var lines = new List<string>();
        foreach (var line in invoice.Lines)
            lines.Add($"{line.Description}: {line.NetAmount}");
        // TODO: include the billing address block in the header
#pragma warning disable CS0618 // No replacement API is available in the supplied context.
        return RenderApiV1.ToPdf($"Invoice {invoice.Number}", lines);
#pragma warning restore CS0618
    }
}
